using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor.SceneManagement;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing.Editor {
public static class CircuitDrivingVerification {
 public static void Run(){Directory.CreateDirectory("Verification/Components");EditorSceneManager.OpenScene("Assets/HarborValeGreybox/Scenes/HarborVale_CityMap.unity");foreach(var spec in UnityEngine.Object.FindObjectsByType<StarterCarSpecification>())UnityEngine.Object.DestroyImmediate(spec.gameObject);var route=JsonUtility.FromJson<TrialDefinition>(Resources.Load<TextAsset>("FirstDocksideTrial").text);var contract=new CircuitContract{id=Guid.NewGuid().ToString("N"),rivals=CircuitRules.Field(Guid.NewGuid().ToString("N")),entryFee=3000,perRival=1000};var session=new CircuitSession(contract,route);var pilots=new RoadPilot[8];var positions=new Vector3[8];var previous=new Vector3[8];var first=route.checkpoints[0];var mode=Physics.simulationMode;Physics.simulationMode=SimulationMode.Script;var rows=new List<string>();int[] last=new int[8];float[] stall=new float[8];try{for(int i=0;i<8;i++){var entry=i<7?contract.rivals[i]:new CircuitEntrant{name="Actual player chassis fixture",modelId="car_coda",build=new WorkshopBuild{naStage=2,gearboxStage=2,tireStage=2},speedKph=105};var car=TrafficWorld.CreateCar(entry.name,entry.build,0,entry.modelId);var p=car.gameObject.AddComponent<RoadPilot>();p.Car=car;p.Path=route.route.Select(t=>t.Position).ToArray();p.IsRival=p.ClosedCourse=true;p.CruiseKph=entry.speedKph;p.SeedClosedGrid(i%2==1);car.ResetAt(first.Position-first.Forward*(12+(i/2)*10)+Vector3.Cross(Vector3.up,first.Forward)*(i%2==0?1.7f:-1.7f)+Vector3.up*.35f,Quaternion.LookRotation(first.Forward));pilots[i]=p;positions[i]=previous[i]=car.transform.position;TrafficWorld.Agents.Add(p);}Physics.SyncTransforms();for(int n=0;n<30000&&!session.Resolved;n++){for(int i=0;i<8;i++){var racer=i==7?session.Player:session.Rivals[i];pilots[i].Held=racer.State!=TrialState.Running;pilots[i].Car.controlsLocked=pilots[i].Held;pilots[i].Drive(.02f);pilots[i].Car.Tick(.02f);}Physics.Simulate(.02f);for(int i=0;i<8;i++)positions[i]=pilots[i].transform.position;session.Tick(.02f,previous[7],positions[7],previous.Take(7).ToArray(),positions.Take(7).ToArray());for(int i=0;i<8;i++){var racer=i==7?session.Player:session.Rivals[i];if(last[i]==racer.NextGate)stall[i]+=.02f;else{last[i]=racer.NextGate;stall[i]=0;}if(racer.State==TrialState.Running&&(stall[i]>45||pilots[i].NeedsAssistedReset)){pilots[i].RecoverAt(racer.Recover());positions[i]=pilots[i].transform.position;stall[i]=0;}previous[i]=positions[i];}if(n%2000==0)rows.Add("MEASURE seconds="+n*.02f+" gates="+string.Join(",",session.Rivals.Select(s=>s.NextGate).Concat(new[]{session.Player.NextGate}))+" recoveries="+string.Join(",",pilots.Select(p=>p.Recoveries)));}bool passed=session.Resolved&&session.Player.ValidFinish;rows.Add((passed?"PASS ":"FAIL ")+"Eight actual wheel-driven cars complete ordered player circuit: playerGates="+session.Player.NextGate+",beaten="+session.Result?.beaten+",elapsed="+session.Player.Elapsed.ToString("F2"));rows.Add("MEASURE overtakes="+string.Join(",",pilots.Select(p=>p.Overtakes))+" recoveries="+string.Join(",",pilots.Select(p=>p.Recoveries)));rows.Add((pilots.All(p=>p.Car.Wheels.Length==4)?"PASS ":"FAIL ")+"Every car retains its own four wheel contacts, authored engine and dynamic body");File.WriteAllLines("Verification/Components/eight-car-physics.txt",rows);if(!passed)throw new Exception("Eight-car player fixture did not finish");}finally{foreach(var p in pilots)if(p!=null)UnityEngine.Object.DestroyImmediate(p.gameObject);TrafficWorld.Agents.Clear();Physics.simulationMode=mode;}}
 public static void Release(){ComponentsCircuitVerification.Run();InventoryVerification.CheckExistingAssets();Run();RaceAiVerification.Run();HarborValeGreybox.Workshop.Editor.AvCameraVerification.Run();HarborValeGreybox.Workshop.Editor.TurboAudioVerification.Run();HarborValeGreybox.Presentation.Editor.CityArtVerification.Release();}
}
}
